import { describe, expect, it } from "vitest";

import { getKey, postKey } from "@/lib/staticDemo";

// Must produce exactly the keys written by scripts/static_demo/record.py (reference strings generated by it).
describe("static demo request keys", () => {
  it("canonicalises GET paths like the recorder", () => {
    expect(getKey("/api/areas/atbasar/impact?t=-300&include_calculation=false")).toBe("GET /api/areas/atbasar/impact?include_calculation=false&t=-300");
    expect(getKey("/api/areas")).toBe("GET /api/areas");
    expect(getKey("/api/audit?limit=300&area_id=kokshetau&affects_results=true")).toBe("GET /api/audit?affects_results=true&area_id=kokshetau&limit=300");
    expect(getKey("/api/scenarios/x/frames/-320/depth.png?member=BASE")).toBe("GET /api/scenarios/x/frames/-320/depth.png?member=BASE");
    expect(getKey("/api/areas/a/access?t=12.50")).toBe("GET /api/areas/a/access?t=12.5");
  });

  it("canonicalises POST bodies like the recorder (sorted keys, as_of_min ignored)", () => {
    expect(postKey("/api/plan-versions/v1/alternatives", { policy: "BALANCED", weights: { life: 40, infra: 35, economic: 25 }, what_if_unavailable: [], extra_constraints: [] }))
      .toBe('POST /api/plan-versions/v1/alternatives {"extra_constraints":[],"policy":"BALANCED","weights":{"economic":25,"infra":35,"life":40},"what_if_unavailable":[]}');
    expect(postKey("/api/areas/k/bottlenecks/analyze", { bottleneck_ids: ["KBR02"], as_of_min: 0 })).toBe('POST /api/areas/k/bottlenecks/analyze {"bottleneck_ids":["KBR02"]}');
  });
});
